using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, tomato sauce, fresh mozzarella, basil, olive oil", Steps = "1. Roll out dough\n2. Spread sauce\n3. Add mozzarella\n4. Bake at 450°F for 12 min\n5. Top with fresh basil" },
            new() { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, pancetta, eggs, parmesan, black pepper", Steps = "1. Cook pasta al dente\n2. Fry pancetta until crisp\n3. Mix eggs with parmesan\n4. Toss hot pasta with pancetta\n5. Stir in egg mixture off heat" },
            new() { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, yogurt, garam masala, tomato sauce, cream, onion, garlic, ginger", Steps = "1. Marinate chicken in spiced yogurt\n2. Grill or bake chicken\n3. Sauté onion, garlic, ginger\n4. Add tomato sauce and spices\n5. Stir in cream and chicken" },
            new() { Id = 4, Title = "Vegetable Pad Thai", Category = "Asian", Ingredients = "Rice noodles, tofu, bean sprouts, peanuts, lime, tamarind paste, soy sauce, eggs", Steps = "1. Soak rice noodles\n2. Fry tofu until golden\n3. Scramble eggs\n4. Stir-fry noodles with sauce\n5. Top with peanuts and lime" },
            new() { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, taco shells, lettuce, tomato, cheese, sour cream, taco seasoning", Steps = "1. Brown beef with seasoning\n2. Warm taco shells\n3. Assemble with toppings\n4. Serve with salsa" },
            new() { Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate, butter, eggs, sugar, flour", Steps = "1. Melt chocolate and butter\n2. Whisk eggs and sugar\n3. Fold in flour and chocolate\n4. Bake at 425°F for 12 min\n5. Invert onto plate and serve immediately" },
            new() { Id = 7, Title = "Caesar Salad", Category = "Salads", Ingredients = "Romaine lettuce, croutons, parmesan, Caesar dressing, lemon, anchovies", Steps = "1. Tear lettuce into pieces\n2. Make dressing with anchovies, lemon, garlic\n3. Toss lettuce with dressing\n4. Top with croutons and parmesan" },
            new() { Id = 8, Title = "Miso Ramen", Category = "Asian", Ingredients = "Ramen noodles, miso paste, pork broth, soft-boiled egg, chashu pork, nori, green onions", Steps = "1. Prepare pork broth\n2. Dissolve miso paste into broth\n3. Cook noodles\n4. Assemble bowl with toppings\n5. Serve hot" },
        };
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            recipe.TotalRatingPoints += stars;
            recipe.RatingCount++;
        }
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps
        });
    }
}

